//! A test minter, behind the `test-support` feature: it signs `v3` grants as Otto's control
//! plane will, with a key it generates, and makes the malformed and non-canonical variants the
//! tests need. Decision 0012 has the adapter built and tested against a local minter before
//! Otto agrees to the format.
//!
//! Nothing here is used by a running gateway. Every key is generated by the run that uses it,
//! so no key is checked in.

use base64::Engine;
use base64::engine::general_purpose::STANDARD;
use ed25519_dalek::{Signer, SigningKey};
use rand_core::{OsRng, RngCore};

use crate::format::{CANONICAL, GROUP_ORDER, KeyId, VERSION, signed_bytes};
use crate::keys::SPKI_PREFIX;

/// The DER of an Ed25519 PKCS#8 PrivateKeyInfo (RFC 8410) up to the 32-byte seed.
const PKCS8_PREFIX: [u8; 16] = [
    0x30, 0x2e, 0x02, 0x01, 0x00, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x70, 0x04, 0x22, 0x04, 0x20,
];

/// Signs grants with a key of its own.
pub struct TestMinter {
    key: SigningKey,
}

impl TestMinter {
    /// A minter with a key generated from the operating system's randomness.
    pub fn generate() -> Self {
        let mut seed = [0; 32];
        OsRng.fill_bytes(&mut seed);
        Self::from_seed(seed)
    }

    /// A minter with the key the 32-byte seed gives (RFC 8032), for a fixed example.
    pub fn from_seed(seed: [u8; 32]) -> Self {
        Self {
            key: SigningKey::from_bytes(&seed),
        }
    }

    /// The public key's 32 bytes.
    pub fn public_key(&self) -> [u8; 32] {
        self.key.verifying_key().to_bytes()
    }

    /// The public key's ID.
    pub fn key_id(&self) -> KeyId {
        KeyId::of(&self.public_key())
    }

    /// The public key as a key file holds it: PEM, `PUBLIC KEY`.
    pub fn public_key_pem(&self) -> String {
        public_key_pem(&self.public_key())
    }

    /// The private key in PKCS#8 PEM, for the test that a key file holding one is refused.
    pub fn private_key_pem(&self) -> String {
        let mut der = PKCS8_PREFIX.to_vec();
        der.extend_from_slice(&self.key.to_bytes());
        // The armour is built from parts so that no source file holds it.
        pem(&format!("{} {}", "PRIVATE", "KEY"), &der)
    }

    /// A canonical grant with these claims, encoded as `serde_json` writes them.
    pub fn mint(&self, claims: &serde_json::Value) -> String {
        self.mint_bytes(claims.to_string().as_bytes())
    }

    /// A canonical grant whose claims part encodes exactly these bytes, JSON or not.
    pub fn mint_bytes(&self, claims: &[u8]) -> String {
        self.sign(VERSION, self.key_id().as_str(), &CANONICAL.encode(claims))
    }

    /// A grant of these three parts exactly as given, with a canonical signature over them:
    /// for another version, another key ID, or claims encoded non-canonically.
    pub fn sign(&self, version: &str, key_id: &str, encoded_claims: &str) -> String {
        let signature = self.signature(version, key_id, encoded_claims);
        format!(
            "{version}.{key_id}.{encoded_claims}.{}",
            CANONICAL.encode(signature)
        )
    }

    /// The signature over three parts as given.
    pub fn signature(&self, version: &str, key_id: &str, encoded_claims: &str) -> [u8; 64] {
        self.key
            .sign(&signed_bytes(
                version.as_bytes(),
                key_id.as_bytes(),
                encoded_claims.as_bytes(),
            ))
            .to_bytes()
    }
}

/// An Ed25519 public key's 32 bytes as a key file holds them: PEM, `PUBLIC KEY`. The bytes are
/// not checked, so this can wrap a small-order or non-canonical key.
pub fn public_key_pem(key: &[u8; 32]) -> String {
    let mut der = SPKI_PREFIX.to_vec();
    der.extend_from_slice(key);
    pem("PUBLIC KEY", &der)
}

/// The identity point, which has order one: a small-order key.
pub fn small_order_key() -> [u8; 32] {
    let mut key = [0; 32];
    key[0] = 1;
    key
}

fn pem(label: &str, der: &[u8]) -> String {
    let body = STANDARD.encode(der);
    let lines: Vec<&str> = body
        .as_bytes()
        .chunks(64)
        .map(|line| std::str::from_utf8(line).unwrap_or_default())
        .collect();
    format!(
        "-----BEGIN {label}-----\n{}\n-----END {label}-----\n",
        lines.join("\n")
    )
}

/// Bytes in canonical unpadded base64url.
pub fn encode(bytes: &[u8]) -> String {
    CANONICAL.encode(bytes)
}

/// A grant's four parts, split at `.`.
pub fn parts(grant: &str) -> Vec<String> {
    grant.split('.').map(str::to_owned).collect()
}

/// A grant with part `index` (0 to 3) replaced.
pub fn with_part(grant: &str, index: usize, part: &str) -> String {
    let mut parts = parts(grant);
    parts[index] = part.to_owned();
    parts.join(".")
}

/// A canonical part with the `=` padding canonical encoding leaves off. Decodes to the same
/// bytes. `None` if the part needs no padding.
pub fn padded(part: &str) -> Option<String> {
    match part.len() % 4 {
        2 => Some(format!("{part}==")),
        3 => Some(format!("{part}=")),
        _ => None,
    }
}

/// A canonical part with a non-zero trailing bit in its last character. Decodes to the same
/// bytes. `None` if the part has no trailing bits.
pub fn with_trailing_bits(part: &str) -> Option<String> {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    if part.len().is_multiple_of(4) {
        return None;
    }
    let (rest, last) = part.split_at(part.len() - 1);
    let value = ALPHABET.iter().position(|c| last.as_bytes() == [*c])?;
    Some(format!("{rest}{}", char::from(ALPHABET[value ^ 1])))
}

/// The grant with its signature's S replaced by S + ℓ: the same signature, non-canonically.
pub fn with_non_canonical_s(grant: &str) -> String {
    let parts = parts(grant);
    let mut signature = CANONICAL.decode(&parts[3]).unwrap_or_default();
    let mut carry = 0u16;
    for (byte, order) in signature[32..].iter_mut().zip(GROUP_ORDER) {
        let sum = u16::from(*byte) + u16::from(order) + carry;
        *byte = sum.to_le_bytes()[0];
        carry = sum >> 8;
    }
    with_part(grant, 3, &CANONICAL.encode(signature))
}
